# Test calling exception classes with an argument
try:
    raise ValueError("test")
except ValueError as e:
    # Can we call TypeError(e)?
    try:
        te = TypeError(e)
        print(f"TypeError(e) works: {te}")
        print(f"Args: {te.args}")
    except Exception as ex:
        print(f"TypeError(e) failed: {ex}")

    # What about ValueError(e)?
    try:
        ve = ValueError(e)
        print(f"ValueError(e) works: {ve}")
        print(f"Args: {ve.args}")
    except Exception as ex:
        print(f"ValueError(e) failed: {ex}")
